enum TracedPath {
    static func make(_ packed: String) -> NSBezierPath {
        let path = NSBezierPath()
        path.windingRule = .evenOdd
        let values = packed.split(separator: ",").map { CGFloat(Double($0)!) }
        var index = 0
        while index < values.count {
            let op = values[index]
            index += 1
            if op == 0 {
                path.move(to: NSPoint(x: values[index], y: values[index + 1]))
                index += 2
            } else if op == 1 {
                path.line(to: NSPoint(x: values[index], y: values[index + 1]))
                index += 2
            } else if op == 2 {
                path.curve(
                    to: NSPoint(x: values[index + 4], y: values[index + 5]),
                    controlPoint1: NSPoint(x: values[index], y: values[index + 1]),
                    controlPoint2: NSPoint(x: values[index + 2], y: values[index + 3])
                )
                index += 6
            } else {
                path.close()
            }
        }
        return path
    }
}
